public class ConstantProcessor implements Processor {

    public static String NAME = "c";

    private Object constant;
    private final Type type;

    enum Type {
        NAMED_WRITABLE,
        ZONEDDATETIME,
        GENERIC,
        VERSION // Version is in x-pack, so StreamInput/Output cannot manage it as a generic type
    }

    public ConstantProcessor(Object value) {
        this.constant = value;
        if (value instanceof NamedWriteable) {
            type = Type.NAMED_WRITABLE;
        } else if (value instanceof ZonedDateTime) {
            type = Type.ZONEDDATETIME;
        } else if (value instanceof Version) {
            type = Type.VERSION;
        } else {
            type = Type.GENERIC;
        }
    }

    public ConstantProcessor(StreamInput in) throws IOException {
        type = in.readEnum(Type.class);
        switch (type) {
            case NAMED_WRITABLE -> constant = in.readNamedWriteable(ConstantNamedWriteable.class);
            case ZONEDDATETIME -> {
                ZonedDateTime zdt;
                ZoneId zoneId = in.readZoneId();
                zdt = ZonedDateTime.ofInstant(Instant.ofEpochMilli(in.readLong()), zoneId);
                constant = zdt.withNano(in.readInt());
            }
            case VERSION -> constant = new Version(in.readString());
            case GENERIC -> constant = in.readGenericValue();
        }
    }

    @Override
    public void writeTo(StreamOutput out) throws IOException {
        out.writeEnum(type);
        switch (type) {
            case NAMED_WRITABLE -> out.writeNamedWriteable((NamedWriteable) constant);
            case ZONEDDATETIME -> {
                ZonedDateTime zdt = (ZonedDateTime) constant;
                out.writeZoneId(zdt.getZone());
                out.writeLong(zdt.toInstant().toEpochMilli());
                out.writeInt(zdt.getNano());
            }
            case VERSION -> out.writeString(constant.toString());
            case GENERIC -> out.writeGenericValue(constant);
        }
    }

    @Override
    public String getWriteableName() {
        return NAME;
    }

    @Override
    public Object process(Object input) {
        return constant;
    }

    @Override
    public int hashCode() {
        return Objects.hashCode(constant);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) {
            return true;
        }

        if (obj == null || getClass() != obj.getClass()) {
            return false;
        }

        ConstantProcessor other = (ConstantProcessor) obj;
        return Objects.equals(constant, other.constant);
    }

    @Override
    public String toString() {
        return "^" + constant;
    }
}

public abstract class BinaryProcessor implements Processor {

    private final Processor left, right;

    public BinaryProcessor(Processor left, Processor right) {
        this.left = left;
        this.right = right;
    }

    protected BinaryProcessor(StreamInput in) throws IOException {
        left = in.readNamedWriteable(Processor.class);
        right = in.readNamedWriteable(Processor.class);
    }

    @Override
    public final void writeTo(StreamOutput out) throws IOException {
        out.writeNamedWriteable(left);
        out.writeNamedWriteable(right);
        doWrite(out);
    }

    protected abstract void doWrite(StreamOutput out) throws IOException;

    @Override
    public Object process(Object input) {
        Object l = left.process(input);
        if (l == null) {
            return null;
        }
        checkParameter(l);

        Object r = right.process(input);
        if (r == null) {
            return null;
        }
        checkParameter(r);

        return doProcess(l, r);
    }

    /**
     * Checks the parameter (typically for its type) if the value is not null.
     */
    protected void checkParameter(Object param) {
        // no-op
    }

    protected Processor left() {
        return left;
    }

    protected Processor right() {
        return right;
    }

    protected abstract Object doProcess(Object left, Object right);
}

