    LTE(Comparisons::lte, "<=");

    private final BiFunction<Object, Object, Boolean> process;
    private final String symbol;

    BinaryComparisonOperation(BiFunction<Object, Object, Boolean> process, String symbol) {
        this.process = process;
        this.symbol = symbol;
    }

    @Override
    public String symbol() {
        return symbol;
    }

    @Override
    public Boolean apply(Object left, Object right) {
        if (this != NULLEQ && (left == null || right == null)) {
            return null;
        }
        return doApply(left, right);
    }

    @Override
    public final Boolean doApply(Object left, Object right) {
        return process.apply(left, right);
    }

    @Override
    public String toString() {
        return symbol;
    }
}

public static class RegexOperation {

        public static Boolean match(Object value, Pattern pattern) {
            if (pattern == null) {
                return Boolean.TRUE;
            }

            if (value == null) {
                return null;
            }

            return pattern.matcher(value.toString()).matches();
        }

        public static Boolean match(Object value, String pattern) {
            return match(value, pattern, Boolean.FALSE);
        }

        public static Boolean match(Object value, String pattern, Boolean caseInsensitive) {
            if (pattern == null) {
                return Boolean.TRUE;
            }

            if (value == null) {
                return null;
            }

            int flags = 0;
            if (Boolean.TRUE.equals(caseInsensitive)) {
                flags |= Pattern.CASE_INSENSITIVE;
            }
            return Pattern.compile(pattern, flags).matcher(value.toString()).matches();
        }
    }

public enum BinaryLogicOperation implements PredicateBiFunction<Boolean, Boolean, Boolean> {

        AND((l, r) -> {
            if (Boolean.FALSE.equals(l) || Boolean.FALSE.equals(r)) {
                return Boolean.FALSE;
            }
            if (l == null || r == null) {
                return null;
            }
            return Boolean.logicalAnd(l.booleanValue(), r.booleanValue());
        }, "AND"),
        OR((l, r) -> {
            if (Boolean.TRUE.equals(l) || Boolean.TRUE.equals(r)) {
                return Boolean.TRUE;
            }
            if (l == null || r == null) {
                return null;
            }
            return Boolean.logicalOr(l.booleanValue(), r.booleanValue());
        }, "OR");

        private final BiFunction<Boolean, Boolean, Boolean> process;
        private final String symbol;

        BinaryLogicOperation(BiFunction<Boolean, Boolean, Boolean> process, String symbol) {
