        @Override
        public Boolean apply(Boolean left, Boolean right) {
            return process.apply(left, right);
        }

        @Override
        public final Boolean doApply(Boolean left, Boolean right) {
            return null;
        }

        @Override
        public String toString() {
            return symbol;
        }
    }

